dynamic_base:
recursive fn make(n:i64)->i64[2]{var data:i64[]=[n];return[data[0],data[0]+1];}
recursive fn nested(n:i64)->i64[2]{var live:i64[]=[9];var a:i64[2]=make(n);assert(live[0]==9);return a;}
fn main(){var a:i64[2]=make(3);var b:i64[2]=nested(7);assert(a[1]==4);assert(b[1]==8);print("dynamic_base");}

mixed:
struct S{n:i64}
recursive fn make(s:S,a:i64[2])->i64[2]{return[s.n+a[0],s.n+a[1]];}
fn main(){var s:S=S{n:5};var a:i64[2]=[3,4];var b:i64[2]=make(s,a);assert(b[0]==8);assert(b[1]==9);print("mixed");}

nominal_elements:
struct S{n:i64}
recursive fn make(n:i64)->S[2]{return[S{n:n},S{n:n+1}];}
fn main(){var a:S[2]=make(7);assert(a[1].n==8);print("nominal_elements");}
